<table style="width: 100%; border-collapse: collapse; font-family: Arial, sans-serif; font-size: 7.5pt; border: 1.2px solid #000; line-height: 1.1; table-layout: fixed; margin-bottom: -18px;">
    <tr>
        <!-- LEFT SIDE: Billing & Shipping -->
        <td style="width: 50%; vertical-align: top; padding: 2px; border-right: 1.2px solid #000; line-height: 1.1;">
            <div style="font-weight: bold; font-size: 10pt; text-transform: uppercase; margin-bottom: 1px;">
                M/s. {{ doc.customer_name }}
            </div>
            <div style="font-size: 8.5pt; line-height: 1;">
                <div style="margin: 0; padding: 0;">
                    {{ doc.address_display or "" }}
                </div>
                {% if doc.billing_address_gstin %}
                    <div style="margin-top: 4px; border-top: 0.5px solid #eee; padding-top: 2px;">
                        <strong>G.S.T. : </strong>{{ doc.billing_address_gstin }}
                    </div>
                {% endif %}
            </div>

            {% if doc.shipping_address %}
            <div style="border-top: 1px solid #000; margin-top: 5px; padding-top: 2px; font-size: 8.5pt;">
                <div style="margin-bottom: 1px;"><strong><u>Delivery At :</u></strong></div>
                <div style="line-height: 1; margin-bottom: 2px;">
                    {{ doc.shipping_address }}
                </div>
                {% if doc.contact_mobile %}
                    <div style="margin-top: 3px; border-top: 0.5px solid #eee; padding-top: 2px;">
                        <strong>Mob:</strong> {{ doc.contact_mobile }}
                    </div>
                {% endif %}
            </div>
            {% endif %}
        </td>

        <!-- RIGHT SIDE: Metadata (ALIGNED GRID) -->
        <td style="width: 50%; vertical-align: top; padding: 0;">
            <table style="width: 100%; border-collapse: collapse; table-layout: fixed;">
                <!-- Row 1: Order -->
                <tr>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top; white-space: nowrap;">Order No.</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ doc.po_no or "" }}</td>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top; white-space: nowrap;">Order Date</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ frappe.utils.formatdate(doc.po_date) if doc.po_date else "" }}</td>
                </tr>

                <!-- Row 2: Delivery Note (Full Width Span) -->
                {% set dns_list = [] %}{% set dc_strings = [] %}
                {% for item in doc.items %}
                    {% if item.delivery_note and item.delivery_note not in dns_list %}
                        {% set _ = dns_list.append(item.delivery_note) %}
                        {% set dn_date = frappe.db.get_value("Delivery Note", item.delivery_note, "posting_date") %}
                        {% set _ = dc_strings.append(item.delivery_note ~ " (" ~ frappe.utils.formatdate(dn_date, "dd-MM-yy") ~ ")") %}
                    {% endif %}
                {% endfor %}
                <tr>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">D.C. No / Dt</td>
                    <td colspan="3" style="padding: 2px; vertical-align: top;">: {{ dc_strings | join(", ") }}</td>
                </tr>

                <!-- Row 3: Boxes/Due -->
                <tr>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">Total Boxes</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ doc.custom_no_of_boxes__bundles or "" }}</td>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">Payment Due Date</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ frappe.utils.formatdate(doc.due_date) if doc.due_date else "" }}</td>
                </tr>

                <!-- Row 4: LR -->
                <tr>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">L.R. No.</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ doc.lr_no or "" }}</td>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">L.R. Date</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ frappe.utils.formatdate(doc.lr_date) if doc.lr_date else "" }}</td>
                </tr>

                <!-- Row 5: Transport/Vehicle -->
                <tr>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">Transport</td>
