                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top;">Vehicle No.</td>
                    <td style="width: 26%; padding: 2px; vertical-align: top;">: {{ doc.vehicle_no or "" }}</td>
                </tr>

                <!-- Row 6: Transporter ID (Full Width for "One Line" requirement) -->
                <tr>
                <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top; white-space: nowrap;">
                    Transporter ID
                </td>
            <td colspan="3" style="padding: 2px; vertical-align: top; letter-spacing: -0.1px;">
                     : {{ doc.gst_transporter_id or "" }}
                     {% if doc.transporter_name %}
                         - {{ doc.transporter_name }}
                     {% endif %}
                </td>
            </tr>

                <!-- Row 7: Eway Bill -->
                <tr>
                    <td style="font-weight: bold; width: 24%; padding: 2px 0 2px 4px; vertical-align: top; white-space: nowrap;">Eway Bill No.</td>
                    <td colspan="3" style="padding: 2px; vertical-align: top;">: {{ doc.ewaybill or "" }}</td>
                </tr>
            </table>
        </td>
    </tr>
