{% set ns = namespace(line_discount=0.0) %}
{% for item in doc.items %}
    {% set ns.line_discount = ns.line_discount + (item.discount_amount | float or 0) %}
{% endfor %}
{% set overall_discount = doc.discount_amount | float or 0.0 %}

<!-- SINGLE COMMON WRAPPER -->
<div style="margin-top: -18px; font-family: Arial, sans-serif; page-break-inside: avoid;">

    <!-- SECTION A: GST BREAKUP & FINANCIAL SUMMARY -->
    <table style="width:100%; border-collapse:collapse; border-spacing:0; font-size:8pt; line-height:1; border-top: 1.5px solid #000; padding-top: 2px;">
        <tr>
          <!-- LEFT: GST Breakup -->
          <td style="width:62%; vertical-align: bottom; padding:0;">
            <div style="font-weight:bold; font-size:8pt; margin-bottom: 1px;">
                Total Qty: {{ doc.total_qty | int }}{% if doc.custom_no_of_boxes__bundles %} | Boxes: {{ doc.custom_no_of_boxes__bundles }}{% endif %}
            </div>
            <div style="width:100%; margin:0; padding:0; line-height: 0.9;">
                {{ doc.gst_breakup_table or "" }}
            </div>
          </td>

          <!-- RIGHT: Financial Totals (Separated Discounts) -->
          <td style="width:38%; vertical-align: bottom; padding:0 0 0 10px;">
            <table style="width:100%; border-collapse:collapse; border-spacing:0;">

                <!-- GROSS TOTAL: Before any discounts are applied -->
                <tr>
                    <td style="padding:0; text-align:left;">Gross Total</td>
                    <td style="padding:0; text-align:right;">{{ "{:,.2f}".format(doc.net_total + ns.line_discount + overall_discount) }}</td>
                </tr>

                <!-- LINE-WISE DISCOUNT: Sum of item-level discounts -->
                {% if ns.line_discount > 0.01 %}
                <tr>
                    <td style="padding:0; text-align:left; color:#d9534f;">Line-wise Discount (-)</td>
                    <td style="padding:0; text-align:right; color:#d9534f;">- {{ "{:,.2f}".format(ns.line_discount) }}</td>
                </tr>
                {% endif %}

                <!-- OVERALL DISCOUNT: Document-level discount -->
                {% if overall_discount > 0.01 %}
                <tr>
                    <td style="padding:0; text-align:left; color:#d9534f;">Overall Discount (-)</td>
                    <td style="padding:0; text-align:right; color:#d9534f;">- {{ "{:,.2f}".format(overall_discount) }}</td>
                </tr>
                {% endif %}

                <!-- TAXABLE VALUE: The net amount that GST is calculated on -->
                <tr style="border-top:0.5px solid #ccc;">
                    <td style="padding:1px 0 0 0; text-align:left; font-weight:bold;">Taxable Value</td>
                    <td style="padding:1px 0 0 0; text-align:right; font-weight:bold;">{{ "{:,.2f}".format(doc.net_total) }}</td>
                </tr>

                {% for tax in doc.taxes %}
                    {% if tax.tax_amount and (tax.tax_amount > 0.01 or tax.tax_amount < -0.01) %}
                    <tr>
                        <td style="padding:0; text-align:left;">{{ tax.account_head.split(' - ')[0] }}</td>
                        <td style="padding:0; text-align:right;">{{ "{:,.2f}".format(tax.tax_amount) }}</td>
                    </tr>
                    {% endif %}
                {% endfor %}

                {% if doc.rounding_adjustment and (doc.rounding_adjustment > 0.001 or doc.rounding_adjustment < -0.001) %}
                <tr>
                    <td style="padding:0; text-align:left;">Round Off</td>
                    <td style="padding:0; text-align:right;">{{ "{:,.2f}".format(doc.rounding_adjustment) }}</td>
                </tr>
                {% endif %}

                <tr style="background-color:#f2f2f2; border:1px solid #000;">
                    <td style="padding:1px 2px; text-align:left; font-weight:bold; font-size:9pt;">TOTAL ₹</td>
                    <td style="padding:1px 2px; text-align:right; font-weight:bold; font-size:9pt;">{{ "{:,.2f}".format(doc.rounded_total or doc.grand_total) }}</td>
                </tr>
            </table>
          </td>
        </tr>
    </table>
</div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- 1. Logic: Discount Calculation -->
